sys_script_include.script:
var WeatherService = Class.create();

WeatherService.prototype = {
    initialize: function() {},

    getWeather: function(city) {
        try {
            // Step 1: Validate the city name
            city = (city || '').trim();

            if (!city) {
                return {
                    success: false,
                    message: 'Please enter a city name.'
                };
            }

            // Step 2: Search for the city
            var geoRequest = new sn_ws.RESTMessageV2(
                'Weather Geocoding API',
                'Search City'
            );

            geoRequest.setStringParameterNoEscape(
                'city',
                city
            );

            var geoResponse = geoRequest.execute();
            var geoStatus = geoResponse.getStatusCode();
            var geoBody = geoResponse.getBody();

            if (geoStatus != 200) {
                return {
                    success: false,
                    message: 'Geocoding API failed. HTTP status: ' +
                        geoStatus
                };
            }

            var geoData = JSON.parse(geoBody);

            // Step 3: Handle an invalid city
            if (!geoData.results ||
                geoData.results.length === 0) {
                return {
                    success: false,
                    message: 'City not found: ' + city
                };
            }

            var place = geoData.results[0];

            var latitude = place.latitude;
            var longitude = place.longitude;
            var region = place.admin1 || '';

            // Step 4: Retrieve current weather
            var weatherRequest = new sn_ws.RESTMessageV2(
                'Weather Current API',
                'Get Current Weather'
            );

            weatherRequest.setStringParameterNoEscape(
                'latitude',
                String(latitude)
            );

            weatherRequest.setStringParameterNoEscape(
                'longitude',
                String(longitude)
            );

            var weatherResponse = weatherRequest.execute();
            var weatherStatus = weatherResponse.getStatusCode();
            var weatherBody = weatherResponse.getBody();

            if (weatherStatus != 200) {
                return {
                    success: false,
                    message: 'Weather API failed. HTTP status: ' +
                        weatherStatus
                };
            }

            var weatherData = JSON.parse(weatherBody);

            if (!weatherData.current ||
                weatherData.current.temperature_2m === undefined) {
                return {
                    success: false,
                    message: 'Temperature was not returned by the API.'
                };
            }

            var temperature =
                weatherData.current.temperature_2m;

            // Step 5: Return weather data WITHOUT saving a record
            return {
                success: true,
                message: 'Weather retrieved successfully.',
                location: place.name,
                latitude: latitude,
                region: region,
                longitude: longitude,
                temperature: temperature
            };

        } catch (error) {
            gs.error(
                'WeatherService error: ' + error.message
            );

            return {
                success: false,
                message: 'An error occurred while retrieving weather.'
            };
        }
    },

    type: 'WeatherService'
};
